/**
 * File: pclfont.h
 * Description: The LaserJet II's built-in fonts as 300 dpi bitmaps, and the
 *              symbol sets that map its codes to characters. pclfont.c is
 *              generated by tools/printer/pclfont.c from Courier Prime (SIL
 *              Open Font License 1.1, pcl/OFL.txt), and DejaVu Sans Mono for
 *              the characters it lacks (pcl/DEJAVU-LICENSE.txt): Courier at 10
 *              pitch 12 point and 12 pitch 10 point, medium and bold, and Line
 *              Printer at 16.67 pitch 8.5 point, narrowed to its cell.
 */
#ifndef PCL_FONT_H
#define PCL_FONT_H

#include <stdint.h>

typedef struct {
  uint16_t code;  // its character, Unicode
  int8_t left;    // its ink's left edge, dots right of the cursor
  int8_t top;     // its ink's top row, dots above the baseline
  uint8_t width;  // its ink, dots
  uint8_t height;
  uint32_t bits;  // its rows in the font's bits: (width + 7) / 8 bytes a row
} PclGlyph;

typedef struct {
  int32_t pitch;     // characters an inch, x 100
  int32_t height;    // point size, x 100
  uint8_t weight;    // stroke weight: 0 medium, 3 bold
  uint8_t typeface;  // 3 Courier, 0 Line Printer
  uint16_t count;
  const PclGlyph *glyphs;  // in the order of their characters
  const uint8_t *bits;
} PclFont;

#define PCL_FONTS 5
extern const PclFont pcl_fonts[PCL_FONTS];

// Symbol sets: the characters of codes 0xA0-0xFF in Roman-8 (8U, the
// LaserJet's default), and of 0x80-0xFF in PC-8 (10U). Below them each is
// ASCII; ISO Latin 1 (0N) is Unicode's own. 0 is no character.
extern const uint16_t pcl_roman8[96];
extern const uint16_t pcl_pc8[128];

#endif  // PCL_FONT_H
